_profile_user.source:
def _profile_user(profile) -> str:
    return _text(
        getattr(profile, "linked_app_user", None)
        or getattr(profile, "user", None)
    )

_valid_link.source:
def _valid_link(profile) -> str:
    customer = _text(getattr(profile, "linked_erpnext_customer", None))
    if customer and frappe.db.exists("Customer", customer):
        return customer
    return ""

_customer_matches.source:
def _customer_matches(user: str) -> list[str]:
    if not user or not frappe.get_meta("Customer").get_field("user_link"):
        return []
    return frappe.get_all(
        "Customer",
        filters={"user_link": user},
        pluck="name",
        limit=2,
    )

resolve_profile_customer.source:
def resolve_profile_customer(profile, *, create_if_missing: bool = True) -> dict[str, Any]:
    if not profile:
        return {
            "status": "Pending Configuration",
            "customer": "",
            "created": False,
            "reason": "customer profile is required",
        }

    linked = _valid_link(profile)
    if linked:
        return {
            "status": "Resolved",
            "customer": linked,
            "created": False,
            "reason": "",
        }

    if _text(getattr(profile, "approval_status", None)) != "Approved":
        return {
            "status": "Pending Configuration",
            "customer": "",
            "created": False,
            "reason": "customer profile is not approved",
        }

    if not int(getattr(profile, "is_active", 0) or 0):
        return {
            "status": "Pending Configuration",
            "customer": "",
            "created": False,
            "reason": "customer profile is inactive",
        }

    user = _profile_user(profile)
    if not user:
        return {
            "status": "Pending Configuration",
            "customer": "",
            "created": False,
            "reason": "customer profile has no linked app user",
        }

    matches = _customer_matches(user)
    if len(matches) > 1:
        return {
            "status": "Ambiguous",
            "customer": "",
            "created": False,
            "reason": "multiple ERP Customers use the same app user",
        }

    if len(matches) == 1:
        _link_profile(profile, matches[0])
        return {
            "status": "Resolved",
            "customer": matches[0],
            "created": False,
            "reason": "",
        }

    if not create_if_missing:
        return {
            "status": "Pending Configuration",
            "customer": "",
            "created": False,
            "reason": "no ERP Customer is linked to this profile",
        }

    customer, error = _create_customer(profile, user)
    if not customer:
        return {
            "status": "Pending Configuration",
            "customer": "",
            "created": False,
            "reason": error,
        }

    _link_profile(profile, customer.name)
    return {
        "status": "Created",
        "customer": customer.name,
        "created": True,
        "reason": "",
    }
